style.css:
body {
  background: #f3f4f6 !important;
}

ytd-app {
  background: #f3f4f6 !important;
}

ytd-rich-grid-renderer {
  background: transparent !important;
}

ytd-rich-item-renderer {
  border-radius: 20px !important;
}
ytd-rich-item-renderer {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 22px !important;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08) !important;
  overflow: hidden !important;
}

ytd-rich-item-renderer:hover {
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.12) !important;
}
body {
  background: linear-gradient(
    135deg,
    #f8f9fb 0%,
    #eef1f5 50%,
    #f9f9fb 100%
  ) !important;
}

ytd-app {
  background: transparent !important;
}
ytd-masthead {
  background: rgba(255, 255, 255, 0.78) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.9) !important;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.06) !important;
}

ytd-searchbox {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 1px solid rgba(210, 213, 218, 0.7) !important;
  border-radius: 18px !important;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.06) !important;
}

ytd-searchbox:hover {
  box-shadow: 0 5px 16px rgba(0, 0, 0, 0.1) !important;
}
ytd-guide-entry-renderer {
  background: rgba(255, 255, 255, 0.62) !important;
  border-radius: 16px !important;
  margin: 3px 8px !important;
}

ytd-guide-entry-renderer:hover {
  background: rgba(255, 255, 255, 0.9) !important;
}

ytd-mini-guide-entry-renderer {
  border-radius: 14px !important;
}

yt-chip-cloud-chip-renderer {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 1px solid rgba(210, 213, 218, 0.65) !important;
  border-radius: 18px !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05) !important;
}

yt-chip-cloud-chip-renderer:hover {
  background: rgba(255, 255, 255, 0.95) !important;
}
ytd-button-renderer {
  border-radius: 16px !important;
}

ytd-button-renderer yt-button-shape button {
  background: rgba(255, 255, 255, 0.7) !important;
  border: 1px solid rgba(210, 213, 218, 0.65) !important;
  border-radius: 16px !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05) !important;
}

ytd-button-renderer yt-button-shape button:hover {
  background: rgba(255, 255, 255, 0.95) !important;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.1) !important;
}

ytd-menu-renderer {
  border-radius: 16px !important;
}

ytd-menu-renderer yt-icon-button {
  border-radius: 14px !important;
}

ytd-menu-renderer yt-icon-button:hover {
  background: rgba(255, 255, 255, 0.75) !important;
}
ytd-popup-container {
  background: rgba(255, 255, 255, 0.94) !important;
  border-radius: 20px !important;
  border: 1px solid rgba(255, 255, 255, 0.95) !important;
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.14) !important;
  overflow: hidden !important;
}

ytd-menu-popup-renderer {
  background: rgba(255, 255, 255, 0.94) !important;
  border-radius: 18px !important;
}

ytd-menu-service-item-renderer {
  border-radius: 12px !important;
  margin: 3px 6px !important;
}

ytd-menu-service-item-renderer:hover {
  background: rgba(240, 242, 246, 0.9) !important;
}
ytd-watch-flexy {
  background: transparent !important;
}

ytd-watch-metadata {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 22px !important;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.07) !important;
  padding: 16px !important;
}

ytd-comments {
  background: rgba(255, 255, 255, 0.68) !important;
  border: 1px solid rgba(255, 255, 255, 0.85) !important;
  border-radius: 22px !important;
  padding: 16px !important;
}
ytd-player {
  border-radius: 24px !important;
  overflow: hidden !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.14) !important;
}

ytd-player-microformat-renderer {
  background: transparent !important;
}

ytd-video-primary-info-renderer {
  background: rgba(255, 255, 255, 0.65) !important;
  border-radius: 18px !important;
}

ytd-video-secondary-info-renderer {
  background: rgba(255, 255, 255, 0.65) !important;
  border-radius: 18px !important;
  margin-top: 10px !important;
}
ytd-menu-renderer {
  background: rgba(255, 255, 255, 0.68) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 18px !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
  padding: 4px !important;
}

ytd-toggle-button-renderer {
  border-radius: 16px !important;
}

ytd-toggle-button-renderer:hover {
  background: rgba(255, 255, 255, 0.9) !important;
}

ytd-button-renderer {
  border-radius: 16px !important;
}

ytd-button-renderer:hover {
  background: rgba(255, 255, 255, 0.9) !important;
}
